// Generates the extension's theme files from the Lumen tokens, so the design
// file stays the only place a color, font or spacing value is written down.
//
//   node scripts/gen-tokens.mjs           rewrite the generated files
//   node scripts/gen-tokens.mjs --check   exit 1 if they are out of date
//
// tokens.css serves extension pages (light on :root, dark under
// [data-theme="dark"]); tokens.ts serves code that cannot load CSS, such as the
// content script, and layout math such as the 28 px row height.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { format, resolveConfig } from "prettier";

const at = (path) => fileURLToPath(new URL(`../${path}`, import.meta.url));
const SOURCE = at("docs/design/lumen/tokens.json");
export const OUTPUTS = {
  css: at("apps/extension/src/theme/tokens.css"),
  ts: at("apps/extension/src/theme/tokens.ts"),
};
const BANNER =
  "Generated by scripts/gen-tokens.mjs from docs/design/lumen/tokens.json. Edit that file and run `npm run gen:tokens`.";

export function readTokens() {
  return JSON.parse(readFileSync(SOURCE, "utf8"));
}

const px = (value) => Number.parseInt(value, 10);
const styles = (tokens) =>
  tokens.type.groups.flatMap((group) =>
    group.styles.map((style) => ({ ...style, family: group.family })),
  );

function colorLines(tokens, theme) {
  return tokens.color.tokens.map(
    (token) => `  --${token.name}: ${token.value[theme]};`,
  );
}

export function renderTokensCss(tokens) {
  const families = Object.entries(tokens.type.families).map(
    ([name, stack]) => `  --font-${name}: ${stack};`,
  );
  const type = styles(tokens).map(
    (s) =>
      `  --type-${s.name}: ${s.fontWeight} ${s.fontSize}/${s.lineHeight} var(--font-${s.family});`,
  );
  const sizes = [...tokens.spacing.tokens, ...tokens.radius.tokens].map(
    (token) => `  --${token.name}: ${token.value};`,
  );
  return [
    `/* ${BANNER} */`,
    ":root {",
    "  color-scheme: light;",
    ...colorLines(tokens, "light"),
    ...families,
    ...type,
    ...sizes,
    "}",
    ':root[data-theme="dark"] {',
    "  color-scheme: dark;",
    ...colorLines(tokens, "dark"),
    "}",
    "",
  ].join("\n");
}

export function renderTokensTs(tokens) {
  const record = (entries) => JSON.stringify(Object.fromEntries(entries));
  const colors = (theme) =>
    record(tokens.color.tokens.map((t) => [t.name, t.value[theme]]));
  const sizes = (list) => record(list.map((t) => [t.name, px(t.value)]));
  return [
    `// ${BANNER}`,
    `export const colors = { light: ${colors("light")}, dark: ${colors("dark")} } as const;`,
    "export type ColorToken = keyof typeof colors.light;",
    `export const fonts = ${JSON.stringify(tokens.type.families)} as const;`,
    "/** Pixels. `spacing.row` is the height of every tree, table and code row. */",
    `export const spacing = ${sizes(tokens.spacing.tokens)} as const;`,
    "/** Pixels. */",
    `export const radius = ${sizes(tokens.radius.tokens)} as const;`,
    "",
  ].join("\n");
}

async function pretty(text, filepath) {
  return format(text, { ...(await resolveConfig(filepath)), filepath });
}

export async function generateTokenFiles(tokens) {
  return {
    css: await pretty(renderTokensCss(tokens), OUTPUTS.css),
    ts: await pretty(renderTokensTs(tokens), OUTPUTS.ts),
  };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const generated = await generateTokenFiles(readTokens());
  const check = process.argv.includes("--check");
  let stale = false;
  for (const [key, path] of Object.entries(OUTPUTS)) {
    let current = "";
    try {
      current = readFileSync(path, "utf8");
    } catch {
      // A missing file is stale like any other.
    }
    if (current === generated[key]) continue;
    stale = true;
    if (check) console.error(`${path} is out of date; run npm run gen:tokens`);
    else writeFileSync(path, generated[key]);
  }
  if (check && stale) process.exit(1);
  if (!check) console.log("Theme tokens written.");
}
